repo_files.sink.py:
"""Destination storage sink for processed events."""

from typing import List
from event_model import IngestionEvent


class EventSink:
    def __init__(self):
        self.flushed: List[IngestionEvent] = []

    def write_batch(self, events: List[IngestionEvent]) -> int:
        self.flushed.extend(events)
        return len(events)

repo_files.dedup_stream.py:
"""Streaming deduplication processor with window tracking."""

from typing import List
from event_model import IngestionEvent


class DeduplicationStream:
    def __init__(self, window_size: int = 1000):
        self.window_size = window_size
        # BUG: Uses a plain list for seen IDs without recency promotion or O(1) set index.
        # When an existing event is re-encountered, it is not moved to the back of the window,
        # causing premature eviction of active events.
        self._seen_ids: list[str] = []

    def filter_duplicates(self, events: List[IngestionEvent]) -> List[IngestionEvent]:
        unique_events: List[IngestionEvent] = []
        for ev in events:
            if ev.event_id not in self._seen_ids:
                self._seen_ids.append(ev.event_id)
                unique_events.append(ev)
                if len(self._seen_ids) > self.window_size:
                    self._seen_ids.pop(0)
        return unique_events

reference_fix.dedup_stream.py:
"""Streaming deduplication processor with window tracking."""

from collections import OrderedDict
from typing import List
from event_model import IngestionEvent


class DeduplicationStream:
    def __init__(self, window_size: int = 1000):
        self.window_size = window_size
        self._seen: OrderedDict[str, None] = OrderedDict()

    def filter_duplicates(self, events: List[IngestionEvent]) -> List[IngestionEvent]:
        unique_events: List[IngestionEvent] = []
        for ev in events:
            if ev.event_id in self._seen:
                self._seen.move_to_end(ev.event_id)
            else:
                self._seen[ev.event_id] = None
                unique_events.append(ev)
                if len(self._seen) > self.window_size:
                    self._seen.popitem(last=False)
        return unique_events
